it('metric-tensor node carries two contravariant indices', () => {
  function findNode(node: unknown, kind: string): unknown | null {
    if (node === null || typeof node !== 'object') return null;
    const n = node as { kind?: string; args?: unknown[]; of?: unknown; wrt?: unknown };
    if (n.kind === kind) return n;
    for (const child of [n.of, n.wrt, ...(Array.isArray(n.args) ? n.args : [])]) {
      const found = findNode(child, kind);
      if (found !== null) return found;
    }
    return null;
